import BrandsSectionV7 from "./components/brands-section-v7"

export default function Page() {
  return <BrandsSectionV7 />
}

import { Instrument_Serif } from "next/font/google"

import { cn } from "@/lib/utils"

import MarqueeRow from "./marquee-row"
import { rowOneBrands, rowTwoBrands } from "../lib/brands"
import { brandsSectionV7Content } from "../lib/config"

import "../styles/brands-section-v7.css"

const instrumentSerif = Instrument_Serif({
  subsets: ["latin"],
  weight: ["400"],
})

type Props = {
  embedded?: boolean
}

export default function BrandsSectionV7({ embedded = false }: Props) {
  const { heading, subheading, footerLink } = brandsSectionV7Content

  return (
    <section
      className={cn(
        "w-full self-stretch",
        embedded ? "pt-12 md:pt-16" : "py-12 md:py-16 lg:py-20"
      )}
    >
      <div
        className={cn(
          "flex w-full flex-col items-center",
          embedded ? "gap-0" : "mx-auto max-w-4xl px-4"
        )}
      >
        <div className="flex max-w-2xl flex-col items-center gap-3 text-center">
          <h2 className={`${instrumentSerif.className} text-3xl leading-[1.15] tracking-[-0.02em] text-foreground sm:text-4xl lg:text-[2.75rem]`}>
            {heading}
          </h2>
          <p className="max-w-xl text-[0.9375rem] leading-relaxed text-muted-foreground">
            {subheading}
          </p>
        </div>

        <div className="mt-10 flex w-full flex-col gap-4">
          <MarqueeRow brands={rowOneBrands} direction="left" />
          <MarqueeRow brands={rowTwoBrands} direction="right" offset />
        </div>

        <a
          href={footerLink.href}
          className="mt-8 text-sm text-muted-foreground underline-offset-4 transition-colors hover:text-foreground hover:underline"
        >
          {footerLink.label}
        </a>
      </div>
    </section>
  )
}

import type { Brand } from "../lib/brands"
import BrandPill from "./brand-pill"

type MarqueeRowProps = {
  brands: Brand[]
  direction: "left" | "right"
  offset?: boolean
}

function MarqueeTrack({
  brands,
  direction,
  ariaHidden = false,
}: {
  brands: Brand[]
  direction: "left" | "right"
  ariaHidden?: boolean
}) {
  return (
    <div
      className="flex shrink-0 items-center gap-2 px-1 md:gap-2.5"
      role={ariaHidden ? undefined : "list"}
      aria-label={ariaHidden ? undefined : "Brand integrations"}
      aria-hidden={ariaHidden || undefined}
    >
      {brands.map((brand) => (
        <div
          key={ariaHidden ? `dup-${brand.name}` : brand.name}
          role={ariaHidden ? undefined : "listitem"}
          className="flex shrink-0"
        >
          <BrandPill brand={brand} />
        </div>
      ))}
    </div>
  )
}

export default function MarqueeRow({
  brands,
  direction,
  offset = false,
}: MarqueeRowProps) {
  const trackClass =
    direction === "left" ? "bs7-track-left" : "bs7-track-right"

  return (
    <div className="relative w-full min-w-0 overflow-hidden">
      <div
        className="pointer-events-none absolute top-0 left-0 z-1 h-full w-16 bg-linear-to-r from-background to-transparent motion-reduce:hidden"
        aria-hidden
      />
      <div
        className="pointer-events-none absolute top-0 right-0 z-1 h-full w-16 bg-linear-to-l from-background to-transparent motion-reduce:hidden"
        aria-hidden
      />

      <div
        className={`${trackClass} flex w-max flex-nowrap items-center py-1 will-change-transform backface-hidden${offset ? " translate-x-8 md:translate-x-12" : ""}`}
      >
        <MarqueeTrack brands={brands} direction={direction} />
        <MarqueeTrack brands={brands} direction={direction} ariaHidden />
      </div>
    </div>
  )
}

export const brandsSectionV7Content = {
  heading: "Built for the stack you already run",
  subheading:
    "Connect payments, auth, databases, and AI to your product without rebuilding your workflow.",
  footerLink: {
    label: "See all integrations",
    href: "#",
  },
} as const

.bs7-track-left {
  animation: bs7-marquee-left 40s linear infinite;
}

.bs7-track-right {
  animation: bs7-marquee-right 44s linear infinite;
}

@keyframes bs7-marquee-left {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}

@keyframes bs7-marquee-right {
  from {
    transform: translate3d(-50%, 0, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bs7-track-left,
  .bs7-track-right {
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
  }
}

